package app.dayflow.markdown;import android.content.Context;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
final class MarkdownFiles {static String read(InputStream in)throws Exception{if(in==null)throw new IOException("无法读取文档");Reader reader=new InputStreamReader(in,StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT));try{StringBuilder text=new StringBuilder();char[] buffer=new char[8192];int n;while((n=reader.read(buffer))!=-1)text.append(buffer,0,n);return text.toString();}catch(OutOfMemoryError e){throw new IOException("设备可用内存不足，原文件未修改");}}static String markdown(JSONObject r){return r.optString("content");}static void update(Context c,JSONObject r)throws IOException{try{((MainActivity)c).wrote(r);}catch(Exception e){throw new IOException(e);}}static String filename(JSONObject r){String title=r.optString("title",java.time.LocalDate.now().toString()).replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_").trim();if(title.isEmpty())title=java.time.LocalDate.now().toString();if(title.length()>80)title=title.substring(0,80);return title.toLowerCase(java.util.Locale.ROOT).endsWith(".md")?title:title+".md";}}
